import * as actions from "@/app/(roles)/pc/model-management/actions";
import { EditModelForm } from "@/components/pc/model-management/EditModelForm";
import type { Model } from "@/lib/pc/types";

function makeModel(overrides: Partial<Model> = {}): Model {
  return {
    id: "m1", name: "Model A", size: 1_000_000, category: [],
    subscription_redemption: null, symbols: [], symbolBook: [], symbolAudit: [],
    mgmt: 0.02, incentive: 0.2, status: "live", version: "v1",
    materials: [], changes: [], description: null, underlyings: null,
    risk: null, liquidity: null, reporting: null, nav_perf: null,
    mgmt_fee: null, incentive_fee: null, master_ib_account: null,
    ...overrides,
  };
}

function setMgmtFee(value: string) {
  fireEvent.change(screen.getByPlaceholderText("e.g. 2.0"), { target: { value } });
}
function setIncentiveFee(value: string) {
  fireEvent.change(screen.getByPlaceholderText("e.g. 20.0"), { target: { value } });
}
function setSize(value: string) {
  fireEvent.change(screen.getByPlaceholderText("$40,000,000"), { target: { value } });
}
function save() {
  fireEvent.click(screen.getByText("Save changes"));
}

beforeEach(() => {
  vi.clearAllMocks();
  vi.mocked(actions.updateModel).mockResolvedValue({ success: true } as never);
});

describe("FE-6 EditModelForm — mgmt_fee/incentive_fee patch via lib/fee's parseFeePercent", () => {
  it("patches mgmt_fee as a decimal fraction (parsed via @/lib/fee) when the field is edited", async () => {
    const model = makeModel({ mgmt_fee: null });
    render(<EditModelForm model={model} onClose={vi.fn()} onSaved={vi.fn()} />);
    setMgmtFee("2.5");
    save();
    await waitFor(() => expect(actions.updateModel).toHaveBeenCalledTimes(1));
    expect(actions.updateModel).toHaveBeenCalledWith("m1", expect.objectContaining({ mgmt_fee: 0.025 }));
  });

  it("does not include mgmt_fee in the patch when the input is left empty and the model already had null", async () => {
    const model = makeModel({ mgmt_fee: null });
    render(<EditModelForm model={model} onClose={vi.fn()} onSaved={vi.fn()} />);
    setIncentiveFee("25"); // change something else so the patch isn't empty
    save();
    await waitFor(() => expect(actions.updateModel).toHaveBeenCalledTimes(1));
    const patch = vi.mocked(actions.updateModel).mock.calls[0][1] as Record<string, unknown>;
    expect(patch).not.toHaveProperty("mgmt_fee");
  });

  it("clearing a previously-set fee patches it to null (not 0, not a thrown error)", async () => {
    const model = makeModel({ mgmt_fee: 0.02 });
    render(<EditModelForm model={model} onClose={vi.fn()} onSaved={vi.fn()} />);
    setMgmtFee("");
    save();
    await waitFor(() => expect(actions.updateModel).toHaveBeenCalledTimes(1));
    expect(actions.updateModel).toHaveBeenCalledWith("m1", expect.objectContaining({ mgmt_fee: null }));
  });

  it("an unchanged fee field (starting null) is omitted from the patch while a touched sibling field is included", async () => {
    const model = makeModel({ mgmt_fee: null, incentive_fee: null });
    render(<EditModelForm model={model} onClose={vi.fn()} onSaved={vi.fn()} />);
    setIncentiveFee("25");
    save();
    await waitFor(() => expect(actions.updateModel).toHaveBeenCalledTimes(1));
    const patch = vi.mocked(actions.updateModel).mock.calls[0][1] as Record<string, unknown>;
    expect(patch).not.toHaveProperty("mgmt_fee");
    expect(patch.incentive_fee).toBe(0.25);
  });

  it("an unchanged fee field on a model that ALREADY has a fraction fee round-trips stably (no silent 100x shrink)", async () => {
    // Regression test: mgmtFee/incentiveFee must seed from the PERCENT string
    // ("2" for a 0.02 fraction), not the raw fraction ("0.02"), or an
    // untouched field re-parsed via parseFeePercent on save silently shrinks
    // an existing fee by 100x (0.02 -> "0.02" -> parseFeePercent -> 0.0002).
    const model = makeModel({ mgmt_fee: 0.02, incentive_fee: 0.2 });
    render(<EditModelForm model={model} onClose={vi.fn()} onSaved={vi.fn()} />);
    expect(screen.getByPlaceholderText("e.g. 2.0")).toHaveValue("2");
    expect(screen.getByPlaceholderText("e.g. 20.0")).toHaveValue("20");
    setSize("2000000"); // change an unrelated field so the patch isn't empty
    save();
    await waitFor(() => expect(actions.updateModel).toHaveBeenCalledTimes(1));
    const patch = vi.mocked(actions.updateModel).mock.calls[0][1] as Record<string, unknown>;
    expect(patch).not.toHaveProperty("mgmt_fee");
    expect(patch).not.toHaveProperty("incentive_fee");
  });
});
